mapper.select:
SELECT w.work_id AS workId, w.title AS title, w.author_id AS authorId, IFNULL(u.nick_name, CONCAT('user-', w.author_id)) AS authorName, w.work_type AS workType, w.status AS status, w.view_count AS viewCount, w.favorite_count AS favoriteCount, w.sale_count AS saleCount, w.price AS price, w.created_at AS createdAt FROM sys_work w LEFT JOIN sys_user u ON u.user_id = w.author_id
w.is_deleted = 0
AND (w.title LIKE CONCAT('%', #{keyword}, '%') OR u.nick_name LIKE CONCAT('%', #{keyword}, '%'))
AND w.status = #{status}
AND DATE(w.created_at) >= #{startDate}
AND DATE(w.created_at) <= #{endDate}
ORDER BY w.created_at DESC

SELECT u.user_id AS userId, u.user_name AS userName, u.nick_name AS nickName, u.user_type AS userType, u.status AS status, u.email AS email, u.phonenumber AS phonenumber, u.create_time AS createTime FROM sys_user u
AND (u.user_name LIKE CONCAT('%', #{keyword}, '%') OR u.nick_name LIKE CONCAT('%', #{keyword}, '%') OR u.phonenumber LIKE CONCAT('%', #{keyword}, '%'))
AND u.user_type = #{userType}
AND DATE(u.create_time) >= #{startDate}
AND DATE(u.create_time) <= #{endDate}
ORDER BY u.create_time DESC

SELECT r.revenue_id AS revenueId, r.stat_date AS statDate, r.work_id AS workId, IFNULL(w.title, CONCAT('work-', r.work_id)) AS workTitle, r.ad_slot AS adSlot, r.impressions AS impressions, r.clicks AS clicks, r.revenue_amount AS revenueAmount, r.channel AS channel FROM sys_ad_revenue r LEFT JOIN sys_work w ON w.work_id = r.work_id
AND r.stat_date >= #{startDate}
AND r.stat_date <= #{endDate}
ORDER BY r.stat_date DESC, r.revenue_id DESC
